#include <stdio.h>
#include <stdlib.h>

#define MAXN 305
#define MAXV 2705
#define INF 2000000000

int P[MAXN], G[MAXN], a[MAXN];
int dp1[MAXN][MAXV], dp2[MAXN][MAXV];
int best[MAXV];

int main() {
    int N, K, T;
    scanf("%d %d %d", &N, &K, &T);
    for (int i = 1; i <= N; i++) scanf("%d", &P[i]);
    int cnt = 0;
    for (int i = 1; i <= N; i++) {
        scanf("%d", &G[i]);
        if (G[i] == 1) a[++cnt] = i;
    }
    int Vmax = 9 * K;
    int (*prev)[MAXV] = dp1;
    int (*cur)[MAXV] = dp2;

    // i = 1
    for (int j = 1; j <= N; j++) {
        for (int v = 0; v <= Vmax; v++) cur[j][v] = INF;
        int cost = a[1] - j;
        if (cost < 0) cost = -cost;
        int val = P[j];
        if (val <= Vmax) cur[j][val] = cost;
    }
    int (*tmp)[MAXV] = prev;
    prev = cur;
    cur = tmp;

    for (int i = 2; i <= K; i++) {
        int maxV = 9 * i;
        int prevMaxV = 9 * (i - 1);
        for (int v = 0; v <= Vmax; v++) best[v] = INF;
        for (int j = 1; j <= N; j++) {
            int cost = a[i] - j;
            if (cost < 0) cost = -cost;
            int pj = P[j];
            for (int v = pj; v <= maxV; v++) {
                int b = best[v - pj];
                if (b >= INF) cur[j][v] = INF;
                else cur[j][v] = b + cost;
            }
            for (int v = 0; v < pj; v++) cur[j][v] = INF;
            for (int v = 0; v <= prevMaxV; v++) {
                if (prev[j][v] < best[v]) best[v] = prev[j][v];
            }
        }
        tmp = prev;
        prev = cur;
        cur = tmp;
    }

    int ans = 0;
    for (int v = Vmax; v >= 0; v--) {
        int minCost = INF;
        for (int j = 1; j <= N; j++) {
            if (prev[j][v] < minCost) minCost = prev[j][v];
        }
        if (minCost <= T) {
            ans = v;
            break;
        }
    }
    printf("%d\n", ans);
    return 0;
}
