#define MAXR 2705

static int dp0[MAXN][MAXR];
static int dp1[MAXN][MAXR];

int main(void) {
    int N, K;
    long long T;

    if (scanf("%d %d %lld", &N, &K, &T) != 3) return 0;

    int P[MAXN];
    for (int i = 1; i <= N; i++) {
        scanf("%d", &P[i]);
    }

    int s[MAXN];
    int cnt = 0;

    for (int i = 1; i <= N; i++) {
        int g;
        scanf("%d", &g);
        if (g) {
            s[++cnt] = i;
        }
    }

    int (*prev)[MAXR] = dp0;
    int (*cur)[MAXR] = dp1;

    for (int j = 0; j <= N; j++) {
        prev[j][0] = 0;
    }

    for (int i = 1; i <= K; i++) {
        int maxPrev = 9 * (i - 1);
        int maxCur = 9 * i;
        int si = s[i];

        for (int r = 0; r <= maxCur; r++) {
            cur[i - 1][r] = INF;
        }

        for (int j = i; j <= N; j++) {
            int pj = P[j];
            int move = si > j ? si - j : j - si;

            int *curPrevRow = cur[j - 1];
            int *prevRow = prev[j - 1];
            int *curRow = cur[j];

            for (int r = 0; r <= maxCur; r++) {
                int best = curPrevRow[r];
                int rp = r - pj;

                if (rp >= 0 && rp <= maxPrev) {
                    int pc = prevRow[rp];
                    if (pc < INF) {
                        int cand = pc + move;
                        if (cand < best) {
                            best = cand;
                        }
                    }
                }

                curRow[r] = best;
            }
        }

        int (*tmp)[MAXR] = prev;
        prev = cur;
        cur = tmp;
    }

    int ans = 0;
    int maxR = 9 * K;

    for (int r = 0; r <= maxR; r++) {
        if ((long long)prev[N][r] <= T) {
            ans = r;
        }
    }

    printf("%d\n", ans);

    return 0;
}
